import{_ as a,a as o,c as n,ac as t}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"第二册：实践与进步 · 全册易错点 · 第50–73课","description":"逐课检查常见错误、适用边界和正确表达。","frontmatter":{"title":"第二册：实践与进步 · 全册易错点 · 第50–73课","description":"逐课检查常见错误、适用边界和正确表达。","splitFrom":"life/english/new-concept/book-2/mistakes.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第二册：实践与进步 · 全册易错点","summary":"逐课检查常见错误、适用边界和正确表达。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · 全册易错点 · 第25–49课","link":"/life/english/new-concept/book-2/mistakes-part-02"},"next":{"text":"第二册：实践与进步 · 全册易错点 · 第74–96课","link":"/life/english/new-concept/book-2/mistakes-part-04"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · 全册易错点 · 第25–49课","link":"/life/english/new-concept/book-2/mistakes-part-02"},"next":{"text":"第二册：实践与进步 · 全册易错点 · 第74–96课","link":"/life/english/new-concept/book-2/mistakes-part-04"}},"headers":[],"relativePath":"life/english/new-concept/book-2/mistakes-part-03.md","filePath":"life/english/new-concept/book-2/mistakes-part-03.md"}'),l={name:"life/english/new-concept/book-2/mistakes-part-03.md"};function i(s,e,r,h,p,d){return o(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="第二册-实践与进步-·-全册易错点-·-第50–73课" tabindex="-1">第二册：实践与进步 · 全册易错点 · 第50–73课 <a class="header-anchor" href="#第二册-实践与进步-·-全册易错点-·-第50–73课" aria-label="Permalink to &quot;第二册：实践与进步 · 全册易错点 · 第50–73课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-2/mistakes">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-2/overview">本册介绍</a> · <a href="/life/english/new-concept/book-2/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-2/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-2/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-2/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-2/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-2/review">综合复习与自测</a></p><h2 id="l50-·-过去完成时与先后关系" tabindex="-1">L50 · 过去完成时与先后关系 <a class="header-anchor" href="#l50-·-过去完成时与先后关系" aria-label="Permalink to &quot;L50 · 过去完成时与先后关系 {#l50-·-过去完成时与先后关系}&quot;">​</a></h2><p>get out of 常用于小汽车，get off 常用于公共汽车；不能在所有交通方式中机械互换。</p><p><strong>对照例句：</strong> By the time I asked, the bus had passed my stop.</p><p>By the time 从句 asked 定位过去时刻，had passed 说明更早已发生的事件；my stop 是目的站。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-050">回看讲解和练习</a></p><h2 id="l51-·-完成进行时与持续活动" tabindex="-1">L51 · 完成进行时与持续活动 <a class="header-anchor" href="#l51-·-完成进行时与持续活动" aria-label="Permalink to &quot;L51 · 完成进行时与持续活动 {#l51-·-完成进行时与持续活动}&quot;">​</a></h2><p>since two weeks 错误，持续长度用 for；since two weeks ago 才引出起点。</p><p><strong>对照例句：</strong> Tess has been avoiding sweet snacks for two weeks.</p><p>has been avoiding 是完成进行时，for two weeks 是持续长度，sweet snacks 是宾语。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-051">回看讲解和练习</a></p><h2 id="l52-·-现在完成时与过去时间" tabindex="-1">L52 · 现在完成时与过去时间 <a class="header-anchor" href="#l52-·-现在完成时与过去时间" aria-label="Permalink to &quot;L52 · 现在完成时与过去时间 {#l52-·-现在完成时与过去时间}&quot;">​</a></h2><p>leaves 是 leaf 的复数；不能写 leafs 来表示这里的树叶。</p><p><strong>对照例句：</strong> Fallen leaves have covered the path outside our classroom.</p><p>Fallen leaves 是复数主语，have covered 为完成时；outside our classroom 修饰 path。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-052">回看讲解和练习</a></p><h2 id="l53-·-被动语态与信息重点" tabindex="-1">L53 · 被动语态与信息重点 <a class="header-anchor" href="#l53-·-被动语态与信息重点" aria-label="Permalink to &quot;L53 · 被动语态与信息重点 {#l53-·-被动语态与信息重点}&quot;">​</a></h2><p>caused from 不合常见搭配；被动原因用 caused by。</p><p><strong>对照例句：</strong> The power failure was caused by a damaged wire.</p><p>failure 为单数主语，was caused 是过去被动，by 引出原因；damaged 是过去分词作定语。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-053">回看讲解和练习</a></p><h2 id="l54-·-时间、原因与让步从句" tabindex="-1">L54 · 时间、原因与让步从句 <a class="header-anchor" href="#l54-·-时间、原因与让步从句" aria-label="Permalink to &quot;L54 · 时间、原因与让步从句 {#l54-·-时间、原因与让步从句}&quot;">​</a></h2><p>run 的过去式是 ran，过去分词才是 run；不能在简单过去叙事中写 jam run。</p><p><strong>对照例句：</strong> As soon as I opened the jar, jam ran over my fingers.</p><p>As soon as 引出开罐动作，ran 为 run 的过去式；over my fingers 描述流过的表面。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-054">回看讲解和练习</a></p><h2 id="l55-·-一般过去时与事件顺序" tabindex="-1">L55 · 一般过去时与事件顺序 <a class="header-anchor" href="#l55-·-一般过去时与事件顺序" aria-label="Permalink to &quot;L55 · 一般过去时与事件顺序 {#l55-·-一般过去时与事件顺序}&quot;">​</a></h2><p>gold 是不可数物质名词，通常不写 a gold；a piece of gold 才表示一块。</p><p><strong>对照例句：</strong> People once believed that the field contained gold.</p><p>believed 是主句过去式，that 从句 contained 是当时的信念内容，不代表作者认可它为事实。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-055">回看讲解和练习</a></p><h2 id="l56-·-比较级与比较范围" tabindex="-1">L56 · 比较级与比较范围 <a class="header-anchor" href="#l56-·-比较级与比较范围" aria-label="Permalink to &quot;L56 · 比较级与比较范围 {#l56-·-比较级与比较范围}&quot;">​</a></h2><p>more faster 重复比较标记；用 faster 或 much faster。</p><p><strong>对照例句：</strong> The new car was much faster than the team&#39;s previous model.</p><p>much 修饰比较级 faster，than 后明确比较对象；previous model 与 new car 都指车型。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-056">回看讲解和练习</a></p><h2 id="l57-·-情态动词的意义与形式" tabindex="-1">L57 · 情态动词的意义与形式 <a class="header-anchor" href="#l57-·-情态动词的意义与形式" aria-label="Permalink to &quot;L57 · 情态动词的意义与形式 {#l57-·-情态动词的意义与形式}&quot;">​</a></h2><p>Would you like seeing 通常不是提出这次邀请的用法；用 Would you like to see。</p><p><strong>对照例句：</strong> Would you like to see a different size?</p><p>Would you like 后接 to see，a different size 是宾语；would 在此不表过去时间。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-057">回看讲解和练习</a></p><h2 id="l58-·-时间、原因与让步从句" tabindex="-1">L58 · 时间、原因与让步从句 <a class="header-anchor" href="#l58-·-时间、原因与让步从句" aria-label="Permalink to &quot;L58 · 时间、原因与让步从句 {#l58-·-时间、原因与让步从句}&quot;">​</a></h2><p>Although ..., but ... 在标准英语中不作这种成对连接；保留一个连接词。</p><p><strong>对照例句：</strong> Although the flood damaged the garden, it led to better drainage.</p><p>Although 从句承认不利事实，主句 led to 引出后续结果；it 指 flood。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-058">回看讲解和练习</a></p><h2 id="l59-·-动词、宾语与补足语" tabindex="-1">L59 · 动词、宾语与补足语 <a class="header-anchor" href="#l59-·-动词、宾语与补足语" aria-label="Permalink to &quot;L59 · 动词、宾语与补足语 {#l59-·-动词、宾语与补足语}&quot;">​</a></h2><p>lets the cat to enter 多了 to；allows the cat enter 则少了 to。</p><p><strong>对照例句：</strong> The new flap lets the cat enter without waking us.</p><p>lets 为单数谓语，the cat 是宾语，enter 是原形补足语；without waking 为介词加动名词。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-059">回看讲解和练习</a></p><h2 id="l60-·-将来表达与安排" tabindex="-1">L60 · 将来表达与安排 <a class="header-anchor" href="#l60-·-将来表达与安排" aria-label="Permalink to &quot;L60 · 将来表达与安排 {#l60-·-将来表达与安排}&quot;">​</a></h2><p>predict 不等于 promise；前者是判断未来，后者是作出承担义务的承诺。</p><p><strong>对照例句：</strong> The guide predicted that we would see clear skies by evening.</p><p>predicted 为过去报告动词，would see 是从过去视角看将来，by evening 给出截止时间。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-060">回看讲解和练习</a></p><h2 id="l61-·-被动语态与信息重点" tabindex="-1">L61 · 被动语态与信息重点 <a class="header-anchor" href="#l61-·-被动语态与信息重点" aria-label="Permalink to &quot;L61 · 被动语态与信息重点 {#l61-·-被动语态与信息重点}&quot;">​</a></h2><p>will have tested 若主语是 camera 会变成摄像机执行测试；此处需 been 表被动。</p><p><strong>对照例句：</strong> By Friday, the replacement camera will have been tested twice.</p><p>will have been tested 为将来完成时被动，By Friday 给出截止点，twice 是次数。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-061">回看讲解和练习</a></p><h2 id="l62-·-完成进行时与持续活动" tabindex="-1">L62 · 完成进行时与持续活动 <a class="header-anchor" href="#l62-·-完成进行时与持续活动" aria-label="Permalink to &quot;L62 · 完成进行时与持续活动 {#l62-·-完成进行时与持续活动}&quot;">​</a></h2><p>had been planted 是被动或状态相关结构，不表示志愿者持续播种；用 planting。</p><p><strong>对照例句：</strong> The volunteers had been planting seeds for hours when the rain began.</p><p>had been planting 强调雨开始前持续的活动，when rain began 提供过去参照点。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-062">回看讲解和练习</a></p><h2 id="l63-·-间接引语与视角转换" tabindex="-1">L63 · 间接引语与视角转换 <a class="header-anchor" href="#l63-·-间接引语与视角转换" aria-label="Permalink to &quot;L63 · 间接引语与视角转换 {#l63-·-间接引语与视角转换}&quot;">​</a></h2><p>asked me to not repeat 有时可见，但常规教学优先 not to repeat；did not ask 与 asked not 不同。</p><p><strong>对照例句：</strong> The host asked me not to repeat the joke.</p><p>asked 后接 me，再用 not to repeat 转述否定请求；the joke 是 repeat 的宾语。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-063">回看讲解和练习</a></p><h2 id="l64-·-非真实条件句" tabindex="-1">L64 · 非真实条件句 <a class="header-anchor" href="#l64-·-非真实条件句" aria-label="Permalink to &quot;L64 · 非真实条件句 {#l64-·-非真实条件句}&quot;">​</a></h2><p>would have open 缺少过去分词；have 后应为 opened。</p><p><strong>对照例句：</strong> If the earlier plan had succeeded, the route would have opened sooner.</p><p>had succeeded 是过去反事实条件，would have opened 是未发生的假设结果，sooner 比较时间早晚。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-064">回看讲解和练习</a></p><h2 id="l65-·-动词、宾语与补足语" tabindex="-1">L65 · 动词、宾语与补足语 <a class="header-anchor" href="#l65-·-动词、宾语与补足语" aria-label="Permalink to &quot;L65 · 动词、宾语与补足语 {#l65-·-动词、宾语与补足语}&quot;">​</a></h2><p>made the elephant to move 在主动句中多余 to；被动才常用 was made to move。</p><p><strong>对照例句：</strong> The keeper made the elephant move towards a basket of fruit.</p><p>made 后接宾语 elephant，再用原形 move 作补足语；towards 只说明方向。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-065">回看讲解和练习</a></p><h2 id="l66-·-完成进行时与持续活动" tabindex="-1">L66 · 完成进行时与持续活动 <a class="header-anchor" href="#l66-·-完成进行时与持续活动" aria-label="Permalink to &quot;L66 · 完成进行时与持续活动 {#l66-·-完成进行时与持续活动}&quot;">​</a></h2><p>honey have been 错误；这里主语 a jar of honey 的核心是 jar，配 has。</p><p><strong>对照例句：</strong> A jar of honey has been leaking inside the delivery van.</p><p>A jar 为单数主语，has been leaking 表持续过程；of honey 说明内容物，inside 为地点。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-066">回看讲解和练习</a></p><h2 id="l67-·-完成进行时与持续活动" tabindex="-1">L67 · 完成进行时与持续活动 <a class="header-anchor" href="#l67-·-完成进行时与持续活动" aria-label="Permalink to &quot;L67 · 完成进行时与持续活动 {#l67-·-完成进行时与持续活动}&quot;">​</a></h2><p>since three months 不合常用表达；用 for three months 或 since March。</p><p><strong>对照例句：</strong> The scientists have been monitoring the volcano since March.</p><p>have been monitoring 是完成进行时，since March 给起点；scientists 是复数主语。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-067">回看讲解和练习</a></p><h2 id="l68-·-动名词与动词搭配" tabindex="-1">L68 · 动名词与动词搭配 <a class="header-anchor" href="#l68-·-动名词与动词搭配" aria-label="Permalink to &quot;L68 · 动名词与动词搭配 {#l68-·-动名词与动词搭配}&quot;">​</a></h2><p>insist to help 应改为 insist on helping；avoid to answer 应为 avoid answering。</p><p><strong>对照例句：</strong> My neighbour insisted on helping me carry the boxes.</p><p>insisted on 是谓语搭配，helping 为介词宾语；help me carry 中 carry 可不带 to。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-068">回看讲解和练习</a></p><h2 id="l69-·-不定式与目的" tabindex="-1">L69 · 不定式与目的 <a class="header-anchor" href="#l69-·-不定式与目的" aria-label="Permalink to &quot;L69 · 不定式与目的 {#l69-·-不定式与目的}&quot;">​</a></h2><p>brake 是刹车，break 是弄坏或休息；二者同音但拼写含义不同。</p><p><strong>对照例句：</strong> The learner was told to stop beside the yellow line.</p><p>was told 是被动转述，to stop 是要求内容，beside the yellow line 为位置。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-069">回看讲解和练习</a></p><h2 id="l70-·-分词修饰与逻辑主语" tabindex="-1">L70 · 分词修饰与逻辑主语 <a class="header-anchor" href="#l70-·-分词修饰与逻辑主语" aria-label="Permalink to &quot;L70 · 分词修饰与逻辑主语 {#l70-·-分词修饰与逻辑主语}&quot;">​</a></h2><p>Waving a flag, the visitors were moved 会让逻辑主语变成游客，不一定符合想表达的意思。</p><p><strong>对照例句：</strong> Waving a red flag, the steward guided the visitors away.</p><p>Waving 的执行者是 the steward；guided 是主句过去式，the visitors 是宾语。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-070">回看讲解和练习</a></p><h2 id="l71-·-非真实条件句" tabindex="-1">L71 · 非真实条件句 <a class="header-anchor" href="#l71-·-非真实条件句" aria-label="Permalink to &quot;L71 · 非真实条件句 {#l71-·-非真实条件句}&quot;">​</a></h2><p>would stopped 缺少 have；过去反事实结果要用 would have stopped。</p><p><strong>对照例句：</strong> If the clock had not been repaired, it would have stopped that winter.</p><p>if 从句 had not been repaired 为过去完成被动；主句 would have stopped 表未发生的过去结果。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-071">回看讲解和练习</a></p><h2 id="l72-·-分词修饰与逻辑主语" tabindex="-1">L72 · 分词修饰与逻辑主语 <a class="header-anchor" href="#l72-·-分词修饰与逻辑主语" aria-label="Permalink to &quot;L72 · 分词修饰与逻辑主语 {#l72-·-分词修饰与逻辑主语}&quot;">​</a></h2><p>A car called Silver Finch. 只是名词短语，不构成完整陈述句。</p><p><strong>对照例句：</strong> A car called Silver Finch completed three test runs.</p><p>called Silver Finch 修饰 A car，completed 才是主句谓语，three test runs 为宾语。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-072">回看讲解和练习</a></p><h2 id="l73-·-现在完成时与过去时间" tabindex="-1">L73 · 现在完成时与过去时间 <a class="header-anchor" href="#l73-·-现在完成时与过去时间" aria-label="Permalink to &quot;L73 · 现在完成时与过去时间 {#l73-·-现在完成时与过去时间}&quot;">​</a></h2><p>five time 应为 five times；不要把 times 误译成五点钟。</p><p><strong>对照例句：</strong> Ella has crossed the border with her family five times this year.</p><p>has crossed 是完成时，five times 为次数，with her family 明确同行者，this year 的范围包含现在。</p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-073">回看讲解和练习</a></p>',123)])])}const f=a(l,[["render",i]]);export{g as __pageData,f as default};
